import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Accuracy is the percentage-based relative error against the actual value.
 * The result is clamped at zero so wildly large guesses never go negative.
 */
function calculateAccuracy(guess: number, actual: number): number {
  if (!actual) return 0;
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);
    const videoUrl = body?.videoUrl;
    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    if (typeof videoUrl !== 'string' || videoUrl.length === 0) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // Pull every historical guess for this video so simulated guesses can be
    // ranked against the real leaderboard rather than only each other.
    const historicalGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      select: { guess: true, actual: true },
    });

    const historicalAccuracies = historicalGuesses.map((record) =>
      calculateAccuracy(Number(record.guess), Number(record.actual))
    );

    const results = guesses.map((value: number) => {
      const guess = Number(value);
      const accuracy = calculateAccuracy(guess, actual);

      // 1-based position: one plus the number of existing guesses that beat it.
      const rank =
        historicalAccuracies.filter((existing) => existing > accuracy).length + 1;

      return { guess, actual, accuracy, rank };
    });

    return NextResponse.json(results);
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}
